import { Group, Mesh, BoxGeometry, CylinderGeometry, IcosahedronGeometry, PointLight, Color } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'ornamental-divider';

  // --- placeholder procedural rule + jewel (shown immediately, replaced by GLB when ready) ---
  const ruleGeo = new BoxGeometry(2.2, 0.035, 0.035);
  const ruleMat = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.5,
    roughness: 0.55,
  });
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.name = 'placeholder-rule';
  group.add(rule);

  const jewelGeo = new IcosahedronGeometry(0.11, 1);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.4,
    metalness: 0.3,
    roughness: 0.3,
    clearcoat: 0.22,
    clearcoatRoughness: 0.2,
  });
  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.name = 'placeholder-jewel';
  jewel.position.set(0, 0, 0.02);
  group.add(jewel);

  // node-local accent rim light (scene provides ambient 0.6 + key 1.2 only)
  const rimLight = new PointLight(new Color(colors.accent), 0.9, 3.5, 2.0);
  rimLight.position.set(0, 0.3, 0.8);
  group.add(rimLight);

  // contact accent halo cylinder (subtle, thin, reads as machined detail)
  const collarGeo = new CylinderGeometry(0.14, 0.14, 0.02, 24);
  const collarMat = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.55,
    roughness: 0.5,
  });
  const collar = new Mesh(collarGeo, collarMat);
  collar.rotation.x = Math.PI / 2;
  collar.position.set(0, 0, 0.0);
  group.add(collar);

  // --- apply cinematic primitives declared in config (none expected here, kept generic) ---
  const primitiveResults = [];
  const primitiveList = config?.cinematicPrimitives ?? [];
  for (const primitive of primitiveList) {
    const applyFn = ctx.primitives?.[primitive.name];
    if (typeof applyFn === 'function') {
      const result = applyFn(group, primitive.params ?? {});
      if (result) primitiveResults.push(result);
    }
  }

  // --- GLB load (async, replaces placeholder) ---
  let glbScene = null;
  let glbDisposed = false;
  if (config.meshUrl) {
    ctx.glbLoader
      .loadGLB(config.meshUrl)
      .then((gltf) => {
        if (glbDisposed) return;
        glbScene = gltf.scene;
        glbScene.name = 'divider-glb';
        group.add(glbScene);
        rule.visible = false;
        jewel.visible = false;
        collar.visible = false;
        // gentle settle-in for the loaded mesh
        glbScene.scale.setScalar(0.98);
        gsap.to(glbScene.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.6,
          ease: 'power3.out',
        });
      })
      .catch(() => {
        // keep placeholder rule/jewel visible on failure
      });
  }

  // --- entrance: weighted rise-in + settle ---
  const startY = group.position.y;
  group.position.y = startY - 0.3;
  group.scale.setScalar(1.04);
  const entranceTl = gsap.timeline();
  entranceTl.to(group.position, {
    y: startY,
    duration: 0.7,
    ease: 'power3.out',
  });
  entranceTl.to(
    group.scale,
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out',
    },
    0
  );

  // --- interaction state ---
  let hoverTl = null;
  let pressTl = null;
  const baseY = startY;

  const onPointerOver = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.to(group.position, {
      y: baseY + 0.15,
      duration: 0.3,
      ease: 'power2.out',
    });
    if (jewelMat) {
      gsap.to(jewelMat, { emissiveIntensity: 1.9, duration: 0.3, ease: 'power2.out' });
    }
  };

  const onPointerOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.to(group.position, {
      y: baseY,
      duration: 0.3,
      ease: 'power2.out',
    });
    if (jewelMat) {
      gsap.to(jewelMat, { emissiveIntensity: 1.4, duration: 0.3, ease: 'power2.out' });
    }
  };

  const onClick = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
    });
    pressTl.to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.2,
      ease: 'power2.out',
    });
    ctx.emit('hub-home.select', { node: 'home-divider' });
  };

  group.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onClick,
  };

  // --- cleanup ---
  group.userData.cleanup = () => {
    glbDisposed = true;

    entranceTl.kill();
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();

    for (const result of primitiveResults) {
      if (result?.timeline) result.timeline.kill();
      if (typeof result?.cleanup === 'function') result.cleanup();
    }

    ruleGeo.dispose();
    ruleMat.dispose();
    jewelGeo.dispose();
    jewelMat.dispose();
    collarGeo.dispose();
    collarMat.dispose();

    if (glbScene) {
      glbScene.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          const mats = Array.isArray(child.material) ? child.material : [child.material];
          for (const m of mats) {
            if (m.map) m.map.dispose();
            m.dispose();
          }
        }
      });
    }

    rimLight.dispose?.();
  };

  return group;
}
